'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const read=p=>fs.readFileSync(path.join(process.cwd(),p),'utf8');
const ui=read('docs/liber-apps/apps/revex/ui-integrity.js');
const sheet=read('docs/liber-apps/apps/revex/mobile-sheet-r142.js');
const has=(text,needle,label)=>assert.ok(text.includes(needle),`${label}: missing ${needle}`);
const no=(text,needle,label)=>assert.ok(!text.includes(needle),`${label}: forbidden ${needle}`);
new Function(sheet);

has(ui,"mobile-sheet-r142.js?v=20260819r142-mobile-sheet1",'current r142 loader');
no(ui,'mobile-design-r139.js','r139 removed from current loader');
no(ui,'mobile-convergence-r140.js','r140 removed from current loader');
no(ui,'chat-embed-r141.js','r141 Secure Chat projection removed');
has(sheet,"const BUILD='20260819r142-mobile-sheet1'",'r142 build');
has(sheet,'reusesExistingNodes:true','reuse existing controls rather than duplicate UI');
has(sheet,'function rememberedNode(key,fallback)','permanent reference helper');
has(sheet,"rememberedNode('bim-rail',document.querySelector('#view-bim>.rail'))",'BIM Model tab retains original rail after first move');
has(sheet,"rememberedNode('bim-inspector',byId('bim-inspector'))",'BIM Properties tab retains original inspector');
has(sheet,"rememberedNode('design-rail',document.querySelector('#view-design>.chapter-rail'))",'Design Selector retains original rail');
has(sheet,"rememberedNode('design-inspector',byId('design-inspector'))",'Design Position retains original inspector');
has(sheet,"a:{label:'Model'",'BIM Model tab');
has(sheet,"b:{label:'Properties'",'BIM Properties tab');
has(sheet,"a:{label:'Selector'",'Design Selector tab');
has(sheet,"b:{label:'Position'",'Design Position tab');
has(sheet,'if(currentView&&currentView!==view){restoreView(currentView);closePane();}','view switches restore original module nodes before moving another module');
has(sheet,"#view-bim>.viewport-wrap",'full-height BIM viewport');
has(sheet,"#view-chat>.chat-head{display:none",'only outer REVEX Chat chrome hidden on mobile projection');
has(sheet,"#chat-frame",'Chat iframe fills projection');
has(sheet,"byId('revex-r109-actions-menu')",'existing mobile actions menu reused for WALLT');
has(sheet,"WALLT Helper / Fixer",'WALLT remains reachable on mobile');
has(sheet,".viewport-tools.viewer-controls{box-sizing:border-box!important;max-width:calc(100% - 24px)",'viewer toolbar constrained to viewport container');
no(sheet,'detailsShell','no replacement details-stack UI');
no(sheet,'cloneNode','no copied/empty controls');
no(sheet,'#view-docs .docs-','Docs layout remains owned by existing r133/r134 code');
no(sheet,'secureChatApp','Secure Chat app internals untouched');
console.log(JSON.stringify({REVEX_R142_MOBILE_SHEET:'PASSED',bim:'persistent-real-node bottom sheet Model|Properties',design:'persistent-real-node bottom sheet Selector|Position',moduleSwitchRestoresNodes:true,bimViewportFull:true,docsOwner:'r133/r134 unchanged',secureChatOwner:'native app unchanged',wallt:'existing actions menu',toolbarContainerBound:true,floatingRewrite:false}));
